window.VOICE = {"engine":"files:/home/user/skyde/video/seslendirme/Salyangoz","gain":1.25,"lines":[{"id":"s-hook","say":"Yağmur yağınca kaldırımı dolduran salyangozlar, aslında günlerdir kabuklarının içinde bu anı bekliyordu.","at":0.1,"dur":6.347,"marks":[0,3.12]},{"id":"s-sumuk","say":"Çünkü salyangoz yürümüyor, kendi ürettiği kaygan bir jölenin üstünde kayıyor. Ve o jölenin neredeyse tamamı su.","at":7.097,"dur":7.61,"marks":[0,1.76,5]},{"id":"s-kapi","say":"Kuru havada attığı her adım, vücudundan su götürüyor. O yüzden kabuğunun ağzını, kuruyan jöleden bir kapıyla mühürleyip bekliyor.","at":15.507,"dur":7.787,"marks":[0,1.72,3.46,5.16]},{"id":"s-yagmur","say":"Yağmur yağınca hava nemli, yer ıslak; kaybettiği su azalıyor. Salyangoz için yağmur, gişesiz bir otoyol.","at":24.044,"dur":7.953,"marks":[0,1.92,3,5.36,6.76]},{"id":"s-muze","say":"Beklemekte de ustalar: Bir müzede, ölü sanılıp kartona yapıştırılan bir çöl salyangozu, dört yıl sonra suya konunca uyanıp yürümüş.","at":32.747,"dur":8.402,"marks":[0,1.68,2.52,5.62]},{"id":"s-cta","say":"Sonra salyangozlara basmamak için parmak ucunda yürüyen arkadaşına gönder.","at":42.549,"dur":4.455,"marks":[0]}],"audio":""};
